function t(){return{tasks:[{text:"В матрице ошибок объект реально положительный, а модель предсказала «отрицательный». Как это называется?",type:"choice",answer:"FN (False Negative)",options:["TP (True Positive)","FP (False Positive)","TN (True Negative)","FN (False Negative)"],hint:"Модель пропустила реально положительный объект",difficulty:"Легко"},{text:"Почему Accuracy может вводить в заблуждение на несбалансированных данных?",type:"choice",answer:"Модель, всегда предсказывающая мажоритарный класс, получит высокую Accuracy, не находя ни одного редкого случая",options:["Accuracy вообще нельзя посчитать на таких данных","Модель, всегда предсказывающая мажоритарный класс, получит высокую Accuracy, не находя ни одного редкого случая","Accuracy считается только для регрессии","Accuracy всегда равна 50%"],hint:'Пример: 99% писем не спам — модель "всегда не спам" даст Accuracy=99%',difficulty:"Средне"},{text:"Что показывает Precision?",type:"choice",answer:"Из всех объектов, названных моделью положительными, какая доля действительно положительная",options:["Из всех реально положительных — сколько нашли","Из всех объектов, названных моделью положительными, какая доля действительно положительная","Долю верных ответов среди всех предсказаний","Площадь под ROC-кривой"],hint:"TP / (TP + FP)",difficulty:"Средне"},{text:"Recall — это то же самое, что...",type:"choice",answer:"TPR (True Positive Rate)",options:["FPR","TPR (True Positive Rate)","Precision","Accuracy"],hint:"Из всех реально положительных — какую долю нашли",difficulty:"Средне"},{text:"Для какой задачи важнее высокий Recall, а не Precision?",type:"choice",answer:"Диагностика опасной болезни — пропустить больного опаснее, чем перестраховаться",options:["Спам-фильтр, где важно не потерять письма","Диагностика опасной болезни — пропустить больного опаснее, чем перестраховаться","Определение цвета объекта на фото","Recall всегда важнее Precision без исключений"],hint:"Пропуск (FN) в медицине может стоить жизни",difficulty:"Сложно"},{text:"Что означает AUC-ROC = 0.5?",type:"choice",answer:"Модель угадывает не лучше случайного гадания",options:["Модель работает идеально","Модель угадывает не лучше случайного гадания","Модель всегда ошибается","Данные несбалансированы"],hint:"Диагональ на ROC-кривой соответствует AUC=0.5",difficulty:"Средне"},{text:"Когда PR-AUC информативнее ROC-AUC?",type:"choice",answer:"На сильно несбалансированных данных (редкий положительный класс)",options:["Когда данные идеально сбалансированы","На сильно несбалансированных данных (редкий положительный класс)","Только в задачах регрессии","PR-AUC никогда не используют на практике"],hint:"Пример — мошенничество, редкая болезнь",difficulty:"Сложно"},{text:"Чем RMSE отличается от MSE?",type:"choice",answer:"RMSE — это корень из MSE, возвращает ошибку в исходных единицах измерения",options:["RMSE и MSE — это одно и то же","RMSE — это корень из MSE, возвращает ошибку в исходных единицах измерения","RMSE считается только для классификации","RMSE всегда больше MSE в 10 раз"],hint:'MSE даёт ошибку в "квадратных" единицах',difficulty:"Средне"},{text:"Почему MAE более устойчива к выбросам, чем MSE?",type:"choice",answer:"MAE берёт модуль ошибки, а MSE возводит её в квадрат, сильно увеличивая вклад редких больших ошибок",options:["MAE вообще не учитывает большие ошибки","MAE берёт модуль ошибки, а MSE возводит её в квадрат, сильно увеличивая вклад редких больших ошибок","MAE считается только по положительным значениям","Разницы между MAE и MSE нет"],hint:"Квадрат резко увеличивает влияние больших промахов",difficulty:"Сложно"},{text:"Что означает R² = 0 у регрессионной модели?",type:"choice",answer:"Модель объясняет разброс данных не лучше, чем предсказание одного среднего значения",options:["Модель работает идеально","Модель объясняет разброс данных не лучше, чем предсказание одного среднего значения","В данных нет ошибок","R² не может быть равен 0"],hint:"R²=1 — идеально, R²=0 — как наивное среднее",difficulty:"Средне"}]}}export{t as default};
